style.css:
@-moz-document domain("youtube.com") {
/* ===== 1. Set Font (customize here) ===== */
    * {
        font-family: "Monotype Corsiva", sans-serif !important;
    }

    /* ===== 2. Background Wallpaper ===== */
    body::before {
        content: '';
        position: fixed;
        top: 0;
        left: 0;
        width: 100vw;
        height: 100vh;
        background-image: url("https://i.postimg.cc/DZxqnSLg/764a0a214cd8d077fce61134b25bfee5.jpg");
        background-size: cover;
        background-position: center;
        opacity: 0.08;
        z-index: -1;
    }

    /* ===== 3. Header Decoration ===== */
    #masthead::after {
        content: '';
        position: absolute;
        top: 6px;
        right: 60px;
        width: 50px;
        height: 50px;
        background-image: url("https://i.postimg.cc/j2WJTZsx/430861.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        pointer-events: none;
    }

    /* ===== 4. Progress Bar Icon ===== */
    .ytp-scrubber-button::after {
        content: '';
        display: block;
        width: 40px;
        height: 40px;
        background-image: url("https://i.postimg.cc/15qNYCCM/message-Image-1739882637472.jpg");
        background-size: contain;
        background-repeat: no-repeat;
        position: absolute;
        top: -30px;
        left: -12px;
        z-index: 10;
        pointer-events: none;
    }

    .ytp-scrubber-button {
        background-color: transparent !important;
    }

    /* ===== 5. Subscribe Button Icon ===== */
    ytd-subscribe-button-renderer::after {
        content: '';
        display: inline-block;
        width: 24px;
        height: 24px;
        background-image: url("https://i.postimg.cc/NFrLSF4L/6b6f04eececcf6fdee35b67c4079c0e7.jpg");
        background-size: cover;
        margin-left: 8px;
        vertical-align: middle;
    }

    /* ===== 6. Sidebar Character (Bottom Left) ===== */
    #guide-inner-bottom::after {
        content: '';
        display: block;
        width: 80px;
        height: 80px;
        background-image: url("https://i.postimg.cc/cJ4Rj78H/8181571cc55945b53fc2e26121dd2a52.png");
        background-size: contain;
        background-repeat: no-repeat;
        margin: 20px auto 0 auto;
    }

    /* ===== 7. Theme Colors ===== */
    body, ytd-app {
        background-color: #001a33 !important;
        color: #e0f7ff !important;
    }

    ytd-masthead, #container.ytd-masthead {
        background-color: #1c3aa9 !important;
    }

    #guide, ytd-mini-guide-renderer, ytd-rich-grid-renderer {
        background-color: #001a33 !important;
    }

    a, button, yt-icon-button {
        color: #ffd700 !important;
    }

    .ytp-play-progress {
        background-color: #ffd700 !important;
    }

    .ytp-load-progress,
    .ytp-progress-bar {
        background-color: #1c3aa9 !important;
    }
}
